-- bc-telemetry storage layout, version 1, for PostgreSQL.
--
-- Generated by bc-telemetry-gen. Do not edit.
-- Apply it once, to a database that has no `telemetry` schema; it is one transaction, so it
-- lands whole or not at all. It holds the data — the tables, their indexes and what they are
-- kept by — and the version that data is at. Two files of their own beside this one are code,
-- applied after it and again whenever they change: functions.sql, the maintenance, erasure and
-- ingest steps, and views.sql, the typed views of the definitions.

BEGIN;

CREATE SCHEMA telemetry;

-- The version this file leaves the database at. A deployment reads it to tell which layout is
-- live, and a migration to a later version replaces it.
CREATE FUNCTION telemetry.layout_version() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 1 $$;

-- ---------------------------------------------------------------------------------------------
-- The three tables. Every record is stored as emitted and aggregated only when read. Each table
-- is partitioned by UTC day on `time`, and holds no default partition: a row with no partition
-- for its day is dropped and counted by the ingest step, never parked where it would block the
-- next day's partition.
--
-- Columns every table carries:
--   time            the span's start, or the record's time
--   record_id       the record's identity; with `time`, the primary key
--   module          the declaring module; null for a record no definition declared
--   name            the item's name within its module; '' for a log no definition declared
--   schema_version  the module's version when the record was written; null exactly when module is
--   service_name    the emitting process
--   organization    the tenant, where the writer's process has one
--   customer        the customer a record is about, for erasure and per-customer retention
--   trace_id, span_id  correlation; required on spans
--   attributes      an object of the declared attributes or fields, each key once
-- ---------------------------------------------------------------------------------------------

CREATE TABLE telemetry.spans (
    time            timestamptz NOT NULL,
    record_id       text        NOT NULL,
    module          text,
    name            text        NOT NULL,
    schema_version  integer,
    service_name    text        NOT NULL,
    organization    text,
    customer        text,
    trace_id        text        NOT NULL,
    span_id         text        NOT NULL,
    attributes      jsonb       NOT NULL,
    end_time        timestamptz NOT NULL,
    parent_span_id  text,
    kind            text        NOT NULL,
    status          text        NOT NULL,
    status_message  text        NOT NULL,
    events          jsonb       NOT NULL,
    PRIMARY KEY (time, record_id),
    CONSTRAINT spans_module_and_version_go_together
        CHECK ((module IS NULL) = (schema_version IS NULL)),
    CONSTRAINT spans_status_is_known CHECK (status IN ('unset', 'ok', 'error')),
    CONSTRAINT spans_attributes_are_an_object CHECK (jsonb_typeof(attributes) = 'object'),
    CONSTRAINT spans_events_are_an_array CHECK (jsonb_typeof(events) = 'array')
) PARTITION BY RANGE (time);

CREATE TABLE telemetry.metrics (
    time            timestamptz NOT NULL,
    record_id       text        NOT NULL,
    module          text,
    name            text        NOT NULL,
    schema_version  integer,
    service_name    text        NOT NULL,
    organization    text,
    customer        text,
    trace_id        text,
    span_id         text,
    attributes      jsonb       NOT NULL,
    kind            text        NOT NULL,
    value           double precision NOT NULL,
    PRIMARY KEY (time, record_id),
    CONSTRAINT metrics_module_and_version_go_together
        CHECK ((module IS NULL) = (schema_version IS NULL)),
    CONSTRAINT metrics_kind_is_known CHECK (kind IN ('counter', 'gauge', 'histogram')),
    CONSTRAINT metrics_attributes_are_an_object CHECK (jsonb_typeof(attributes) = 'object')
) PARTITION BY RANGE (time);

-- Logs, and errors too: a reported error is a log record whose name is the error's.
CREATE TABLE telemetry.logs (
    time            timestamptz NOT NULL,
    record_id       text        NOT NULL,
    module          text,
    name            text        NOT NULL,
    schema_version  integer,
    service_name    text        NOT NULL,
    organization    text,
    customer        text,
    trace_id        text,
    span_id         text,
    attributes      jsonb       NOT NULL,
    severity        text        NOT NULL,
    body            text        NOT NULL,
    PRIMARY KEY (time, record_id),
    CONSTRAINT logs_module_and_version_go_together
        CHECK ((module IS NULL) = (schema_version IS NULL)),
    CONSTRAINT logs_severity_is_known
        CHECK (severity IN ('debug', 'info', 'warn', 'error', 'fatal')),
    CONSTRAINT logs_attributes_are_an_object CHECK (jsonb_typeof(attributes) = 'object')
) PARTITION BY RANGE (time);

-- Indexes, declared on the parents so every partition gets them: what a typed view filters on,
-- what a tenant's reads filter on, what an erasure deletes by, and what a trace lookup starts
-- from.
CREATE INDEX spans_by_item ON telemetry.spans (module, name, time);
CREATE INDEX spans_by_organization ON telemetry.spans (organization, time)
    WHERE organization IS NOT NULL;
CREATE INDEX spans_by_customer ON telemetry.spans (organization, customer)
    WHERE customer IS NOT NULL;
CREATE INDEX spans_by_trace ON telemetry.spans (trace_id);

CREATE INDEX metrics_by_item ON telemetry.metrics (module, name, time);
CREATE INDEX metrics_by_organization ON telemetry.metrics (organization, time)
    WHERE organization IS NOT NULL;
CREATE INDEX metrics_by_customer ON telemetry.metrics (organization, customer)
    WHERE customer IS NOT NULL;

CREATE INDEX logs_by_item ON telemetry.logs (module, name, time);
CREATE INDEX logs_by_organization ON telemetry.logs (organization, time)
    WHERE organization IS NOT NULL;
CREATE INDEX logs_by_customer ON telemetry.logs (organization, customer)
    WHERE customer IS NOT NULL;

-- ---------------------------------------------------------------------------------------------
-- What the ingest step reads: the days that have partitions, and the customers erased.
-- ---------------------------------------------------------------------------------------------

-- One row per UTC day whose three partitions exist. Written by `maintain` and by nothing else.
CREATE TABLE telemetry.live_days (
    day date PRIMARY KEY
);

-- One row per erased customer: every record about them whose time is at or before `erased_at`
-- is refused from then on, so a record still queued in some writer when the erasure committed
-- never lands after it. `maintain` removes a row once nothing it could match is still kept.
CREATE TABLE telemetry.erasures (
    organization text,
    customer     text        NOT NULL,
    erased_at    timestamptz NOT NULL
);

-- A process with no tenant erases under a null organization, which a plain unique constraint
-- would let repeat. The ingest step looks a staged row's customer up through this index, so its
-- cost per row does not grow with the number of erasures.
CREATE UNIQUE INDEX erasures_by_subject
    ON telemetry.erasures ((COALESCE(organization, '')), customer);

COMMIT;
